using System;
using UnityEngine;

namespace TheLastFortress
{
    /// <summary>
    /// Asset references the bootstrap needs. Generated by the editor setup scripts. A content asset with
    /// <see cref="mvpDefinitions"/> set runs the multi-night MVP; otherwise the one-wave prototype.
    /// </summary>
    [CreateAssetMenu(menuName = "The Last Fortress/Prototype Content", fileName = "PrototypeContent")]
    public sealed class PrototypeContent : ScriptableObject
    {
        public PrototypeDefinitionsAsset definitions;

        [Tooltip("When set, the scene runs the multi-night MVP with these definitions.")]
        public MvpDefinitionsAsset mvpDefinitions;

        [Header("Entity prefabs")]
        public GameObject keepPrefab;
        public GameObject wallPrefab;
        public GameObject towerPrefab;
        public GameObject gruntPrefab;
        public GameObject housePrefab;
        public GameObject farmPrefab;
        public GameObject trapPrefab;
        public GameObject runnerPrefab;
        public GameObject brutePrefab;
        public GameObject golemPrefab;

        [Tooltip("MVP connected Walls, indexed by WallShape (Isolated, End, Straight, Corner, T, Cross), canonical facing north. Empty keeps the prototype Wall.")]
        public GameObject[] wallShapePrefabs;

        [Tooltip("Uniform scale for enemy views (MVP readability at default zoom). 0 or 1 = prefab scale.")]
        public float enemyScale = 1f;

        [Header("Materials")]
        public Material grass;
        public Material water;
        public Material timberShadow;
        public Material overlay;
        public Material arrow;
        public Material foliage;
        public Material rock;

        [Tooltip("Optional overlay material drawn on top of geometry (route, breach, selection). Falls back to 'overlay'.")]
        public Material overlayOnTop;

        [Header("Layouts")]
        public TextAsset winningLayout;
        public TextAsset losingLayout;
        public TextAsset stressLayout;

        public bool IsMvp => mvpDefinitions != null;

        /// <summary>Explicit per enemy kind; a missing prefab is a setup error, never a Grunt stand-in.</summary>
        public GameObject EnemyPrefabFor(EnemyKind kind)
        {
            GameObject prefab;
            switch (kind)
            {
                case EnemyKind.Grunt: prefab = gruntPrefab; break;
                case EnemyKind.Runner: prefab = runnerPrefab; break;
                case EnemyKind.Brute: prefab = brutePrefab; break;
                case EnemyKind.SiegeGolem: prefab = golemPrefab; break;
                default: throw new ArgumentOutOfRangeException(nameof(kind), kind, null);
            }

            if (prefab == null) throw new InvalidOperationException($"No prefab assigned for {kind} in {name}; run the setup menu.");
            return prefab;
        }

        /// <summary>Explicit per kind; a missing prefab is a setup error, never a silent substitute.</summary>
        public GameObject PrefabFor(BuildingKind kind)
        {
            GameObject prefab;
            switch (kind)
            {
                case BuildingKind.Keep: prefab = keepPrefab; break;
                case BuildingKind.Wall: prefab = wallPrefab; break;
                case BuildingKind.Tower: prefab = towerPrefab; break;
                case BuildingKind.House: prefab = housePrefab; break;
                case BuildingKind.Farm: prefab = farmPrefab; break;
                case BuildingKind.SpikeTrap: prefab = trapPrefab; break;
                default: throw new ArgumentOutOfRangeException(nameof(kind), kind, null);
            }

            if (prefab == null) throw new InvalidOperationException($"No prefab assigned for {kind} in {name}; run the setup menu.");
            return prefab;
        }
    }
}
